class Solution {
public:
    long long maxPower(std::vector<int>& stations, int r, int k) {
        int n = stations.size();
        std::vector<long long> power(n, 0);
        long long cur = 0;
        int init_r = std::min(n - 1, r);
        for (int i = 0; i <= init_r; ++i) cur += stations[i];
        power[0] = cur;
        for (int i = 1; i < n; ++i) {
            if (i + r < n) cur += stations[i + r];
            if (i - r - 1 >= 0) cur -= stations[i - r - 1];
            power[i] = cur;
        }

        auto check = [&](long long target) {
            std::vector<long long> diff(n + 1, 0);
            long long add = 0, used = 0;
            for (int i = 0; i < n; ++i) {
                add += diff[i];
                long long cur_p = power[i] + add;
                if (cur_p < target) {
                    long long need = target - cur_p;
                    used += need;
                    if (used > k) return false;
                    add += need;
                    int pos = std::min(n - 1, i + r);
                    int end = std::min(n, pos + r + 1);
                    diff[end] -= need;
                }
            }
            return true;
        };

        long long lo = *std::min_element(power.begin(), power.end());
        long long hi = lo + k;
        long long ans = lo;
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            if (check(mid)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public long maxPower(int[] stations, int r, int k) {
        int n = stations.length;
        long[] power = new long[n];
        long cur = 0;
        int initR = Math.min(n - 1, r);
        for (int i = 0; i <= initR; i++) cur += stations[i];
        power[0] = cur;
        for (int i = 1; i < n; i++) {
            if (i + r < n) cur += stations[i + r];
            if (i - r - 1 >= 0) cur -= stations[i - r - 1];
            power[i] = cur;
        }

        long lo = power[0];
        for (long p : power) lo = Math.min(lo, p);
        long hi = lo + k;
        long ans = lo;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            if (check(mid, power, r, k, n)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
    private boolean check(long target, long[] power, int r, int k, int n) {
        long[] diff = new long[n + 1];
        long add = 0, used = 0;
        for (int i = 0; i < n; i++) {
            add += diff[i];
            long curP = power[i] + add;
            if (curP < target) {
                long need = target - curP;
                used += need;
                if (used > k) return false;
                add += need;
                int pos = Math.min(n - 1, i + r);
                int end = Math.min(n, pos + r + 1);
                diff[end] -= need;
            }
        }
        return true;
    }
}

var maxPower = function(stations, r, k) {
    const n = stations.length;
    const power = new Array(n).fill(0n);
    let cur = 0n;
    const initR = Math.min(n - 1, r);
    for (let i = 0; i <= initR; i++) cur += BigInt(stations[i]);
    power[0] = cur;
    for (let i = 1; i < n; i++) {
        if (i + r < n) cur += BigInt(stations[i + r]);
        if (i - r - 1 >= 0) cur -= BigInt(stations[i - r - 1]);
        power[i] = cur;
    }

    const check = (target) => {
        const diff = new Array(n + 1).fill(0n);
        let add = 0n, used = 0n;
        const bk = BigInt(k);
        for (let i = 0; i < n; i++) {
            add += diff[i];
            const curP = power[i] + add;
            if (curP < target) {
                const need = target - curP;
                used += need;
                if (used > bk) return false;
                add += need;
                const pos = Math.min(n - 1, i + r);
                const end = Math.min(n, pos + r + 1);
                diff[end] -= need;
            }
        }
        return true;
    };

    let lo = power[0];
    for (const p of power) if (p < lo) lo = p;
    let hi = lo + BigInt(k);
    let ans = lo;
    while (lo <= hi) {
        const mid = (lo + hi) / 2n;
        if (check(mid)) {
            ans = mid;
            lo = mid + 1n;
        } else {
            hi = mid - 1n;
        }
    }
    return Number(ans);
};
